# Parameter recovery: data generated by simulab from known parameters (stored with the data and read back with
# as.data.frame(what = )), fitted by Nestimate, the estimates compared with the truth. A second way of checking the
# estimators beside the outside software of their own files: a Markov chain (build_tna()), a Gaussian graphical
# model (build_cor(), build_pcor()), a mixture of Markov chains (build_mmm()) and a multilevel VAR (build_mlvar()).
# Tolerances are fixed before the run from the sampling error (4 standard errors, bounds stated at each check);
# three seeds each.

recovery <- "independent: recovery of the parameters of simulab %s()"

# A 4-state transition matrix and its initial distribution.
rc_states <- c("A", "B", "C", "D")
rc_transition <- matrix(c(0.50, 0.20, 0.20, 0.10,
                          0.10, 0.60, 0.20, 0.10,
                          0.25, 0.25, 0.40, 0.10,
                          0.15, 0.15, 0.20, 0.50), 4L, 4L, byrow = TRUE, dimnames = list(rc_states, rc_states))
rc_initial <- c(A = 0.4, B = 0.3, C = 0.2, D = 0.1)

# simulab's stored transition table as a matrix (rows from, columns to).
rc_truth <- function(table, states) {
  truth <- matrix(0, length(states), length(states), dimnames = list(states, states))
  truth[cbind(table$from, table$to)] <- table$probability
  truth
}

test_that("build_tna() recovers the transition and initial probabilities of simulab::simulate_markov()", {
  invisible(lapply(c(51L, 52L, 53L), \(seed) {
    simulated <- simulab::simulate_markov(n = 2000L, transition = rc_transition, chain_length = 25L, initial = rc_initial,
                                          seed = seed)
    wide <- subset(as.data.frame(simulated, what = "wide"), select = -id)
    truth <- rc_truth(as.data.frame(simulated, what = "transitions"), rc_states)
    initial <- as.data.frame(simulated, what = "initial_probabilities")
    network <- build_tna(wide)
    # Each row's estimate is a multinomial proportion of the transitions out of that state: 4 SE of the row's
    # largest p (1 - p) over its count.
    from_counts <- table(factor(unlist(wide[, -ncol(wide)], use.names = FALSE), rc_states))
    invisible(lapply(rc_states, \(state) {
      expect_reference(extract_transition_matrix(network)[state, ], truth[state, ], reference = sprintf(recovery, "simulate_markov"),
                       covers = "build_tna()", quantity = sprintf("transitions from %s, seed %d", state, seed),
                       tolerance = 4 * sqrt(max(truth[state, ] * (1 - truth[state, ])) / from_counts[[state]]))
    }))
    expect_reference(extract_initial_probs(network), stats::setNames(initial$probability, initial$state),
                     reference = sprintf(recovery, "simulate_markov"), covers = "build_tna()",
                     quantity = sprintf("initial probabilities, seed %d", seed),
                     tolerance = 4 * sqrt(0.25 / nrow(wide)))
  }))
})

test_that("build_cor() and build_pcor() recover the correlations and partial correlations of simulab::simulate_correlation()", {
  correlation <- matrix(c(1.0, 0.5, 0.3, 0.0, 0.2,
                          0.5, 1.0, 0.4, 0.1, 0.0,
                          0.3, 0.4, 1.0, 0.3, 0.1,
                          0.0, 0.1, 0.3, 1.0, 0.4,
                          0.2, 0.0, 0.1, 0.4, 1.0), 5L, 5L)
  n <- 20000L
  invisible(lapply(c(61L, 62L, 63L), \(seed) {
    simulated <- simulab::simulate_correlation(n = n, means = rep(0, 5L), structure = "custom", correlation = correlation,
                                               seed = seed)
    data <- subset(as.data.frame(simulated), select = -id)
    table <- as.data.frame(simulated, what = "correlation")
    truth <- matrix(table$correlation, 5L, 5L, dimnames = list(names(data), names(data)))
    precision <- solve(truth)
    partial <- -precision / sqrt(outer(diag(precision), diag(precision)))
    diag(truth) <- 0
    diag(partial) <- 0
    # SE of a correlation (1 - rho^2) / sqrt(n), of a partial correlation (1 - rho^2) / sqrt(n - p - 1), at most
    # 1 / sqrt(n - p - 1).
    expect_reference(extract_transition_matrix(build_cor(data)), truth, reference = sprintf(recovery, "simulate_correlation"),
                     covers = "build_cor()", quantity = sprintf("correlations, n = %d, seed %d", n, seed),
                     tolerance = 4 / sqrt(n))
    expect_reference(extract_transition_matrix(build_pcor(data)), partial,
                     reference = sprintf(recovery, "simulate_correlation"), covers = "build_pcor()",
                     quantity = sprintf("partial correlations, n = %d, seed %d", n, seed), tolerance = 4 / sqrt(n - 5 - 1))
  }))
})

test_that("build_mmm() recovers the cluster transition matrices of simulab::simulate_sequence_clusters()", {
  first <- matrix(c(0.8, 0.1, 0.1, 0.1, 0.8, 0.1, 0.1, 0.1, 0.8), 3L, 3L, byrow = TRUE,
                  dimnames = list(c("A", "B", "C"), c("A", "B", "C")))
  second <- matrix(c(0.1, 0.8, 0.1, 0.1, 0.1, 0.8, 0.8, 0.1, 0.1), 3L, 3L, byrow = TRUE, dimnames = dimnames(first))
  invisible(lapply(c(71L, 72L, 73L), \(seed) {
    simulated <- simulab::simulate_sequence_clusters(n = 1000L, transitions = list(first, second), chain_length = 20L,
                                                     proportions = c(0.5, 0.5), seed = seed)
    long <- as.data.frame(simulated)
    wide <- stats::reshape(subset(long, select = c(id, period, state)), direction = "wide", idvar = "id",
                           timevar = "period")
    wide <- subset(wide, select = -id)
    truths <- lapply(split(as.data.frame(simulated, what = "transitions"),
                           as.data.frame(simulated, what = "transitions")$sequence_cluster),
                     \(table) rc_truth(table, c("A", "B", "C")))
    fit <- build_mmm(wide, k = 2L, n_starts = 5L, seed = 1)
    estimates <- lapply(fit$models, \(model) unclass(model$weights)[c("A", "B", "C"), c("A", "B", "C")])
    # The fitted clusters carry no simulab label: each truth is matched to the closer estimate.
    matched <- vapply(truths, \(truth) which.min(vapply(estimates, \(e) sum(abs(e - truth)), numeric(1))), integer(1))
    # Each cluster has about 500 sequences of 19 transitions, about 3000 from each state: 4 SE of p = 0.8 over a
    # count of 2500 (a conservative floor for the share of one state within one cluster).
    invisible(Map(\(truth, index, label) {
      expect_reference(estimates[[index]], truth, reference = sprintf(recovery, "simulate_sequence_clusters"),
                       covers = "build_mmm()", quantity = sprintf("%s transitions, seed %d", label, seed),
                       tolerance = 4 * sqrt(0.8 * 0.2 / 2500))
    }, truths, matched, names(truths)))
  }))
})

test_that("build_mlvar() recovers the temporal coefficients of simulab::simulate_longitudinal()", {
  transition <- matrix(c(0.4, 0.2, 0.0, 0.3), 2L, 2L)
  # Long series (200 occasions) keep the within-person centring bias of order (1 + beta) / occasions (Nickell
  # 1981) below 0.01, a quarter of the tolerance.
  n_people <- 50L
  occasions <- 200L
  invisible(lapply(c(81L, 82L, 83L), \(seed) {
    simulated <- simulab::simulate_longitudinal(n = n_people, occasions = occasions, transition = transition, seed = seed)
    data <- transform(as.data.frame(simulated), day = 1L)
    table <- as.data.frame(simulated, what = "transition")
    truth <- data.frame(outcome = table$row, predictor = table$column, beta = table$coefficient)
    found <- build_mlvar(data, vars = c("variable_1", "variable_2"), id = "id", day = "day", beep = "occasion")
    # Unit innovations and stationary predictors of variance at least 1: the SE of a coefficient is at most
    # 1 / sqrt(n (occasions - 1)).
    expect_reference(coefs(found), truth, reference = sprintf(recovery, "simulate_longitudinal"),
                     covers = "build_mlvar()", quantity = sprintf("temporal coefficients, %d people x %d occasions, seed %d",
                                                                n_people, occasions, seed),
                     tolerance = 4 / sqrt(n_people * (occasions - 1L)), key = c("outcome", "predictor"))
  }))
})
